<?php require_once __DIR__.'/../includes/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')exit;verify_csrf();$allowed=['Enquiry','Contacted','Counselling','Application','Documents Pending','Admitted','Closed'];$status=$_POST['status']??'Enquiry';if(!in_array($status,$allowed,true))$status='Enquiry';$st=$pdo->prepare("UPDATE admissions SET status=? WHERE id=?");$st->execute([$status,(int)$_POST['id']]);flash('Admission status updated.');header('Location: '.url('admin'));